USE DATAFUELDW;
GO

SET NOCOUNT ON;
SET DATEFORMAT ymd;
GO

/*==============================================================================
  SECCIÓN 5 Y 6. CREACIÓN DE TABLAS ORIGINALES Y NUEVAS, CLAVES PRIMARIAS,
                 CLAVES FORÁNEAS, RESTRICCIONES (CHECK / UNIQUE) E ÍNDICES
==============================================================================*/

IF OBJECT_ID(N'dbo.MovimientosCombustible', N'U') IS NOT NULL DROP TABLE dbo.MovimientosCombustible;
IF OBJECT_ID(N'dbo.PedidosEstaciones', N'U') IS NOT NULL DROP TABLE dbo.PedidosEstaciones;
IF OBJECT_ID(N'dbo.Mantenimiento', N'U') IS NOT NULL DROP TABLE dbo.Mantenimiento;
IF OBJECT_ID(N'dbo.PresupuestosAnualesEstacion', N'U') IS NOT NULL DROP TABLE dbo.PresupuestosAnualesEstacion;
IF OBJECT_ID(N'dbo.Equipos', N'U') IS NOT NULL DROP TABLE dbo.Equipos;
IF OBJECT_ID(N'dbo.Estaciones', N'U') IS NOT NULL DROP TABLE dbo.Estaciones;
IF OBJECT_ID(N'dbo.[Detalles de Pedidos]', N'U') IS NOT NULL DROP TABLE dbo.[Detalles de Pedidos];
IF OBJECT_ID(N'dbo.Pedidos', N'U') IS NOT NULL DROP TABLE dbo.Pedidos;
IF OBJECT_ID(N'dbo.Productos', N'U') IS NOT NULL DROP TABLE dbo.Productos;
IF OBJECT_ID(N'dbo.Empleados', N'U') IS NOT NULL DROP TABLE dbo.Empleados;
IF OBJECT_ID(N'dbo.Clientes', N'U') IS NOT NULL DROP TABLE dbo.Clientes;
IF OBJECT_ID(N'dbo.Proveedores', N'U') IS NOT NULL DROP TABLE dbo.Proveedores;
IF OBJECT_ID(N'dbo.Categorias', N'U') IS NOT NULL DROP TABLE dbo.Categorias;
IF OBJECT_ID(N'dbo.TiposCambio', N'U') IS NOT NULL DROP TABLE dbo.TiposCambio;
GO

-- 5.1 Tabla de Soporte Financiero: TiposCambio (2009 - 2026)
CREATE TABLE dbo.TiposCambio (
    IdTipoCambio INT NOT NULL,
    FechaVigencia DATE NOT NULL,
    MonedaOrigen NVARCHAR(10) NOT NULL,
    MonedaDestino NVARCHAR(10) NOT NULL DEFAULT N'USD',
    TipoCambio DECIMAL(18, 4) NOT NULL,
    Fuente NVARCHAR(150) NOT NULL,
    EsRealOVariableSintetica NVARCHAR(40) NOT NULL,
    CONSTRAINT PK_TiposCambio PRIMARY KEY CLUSTERED (IdTipoCambio),
    CONSTRAINT CK_TiposCambio_Positivo CHECK (TipoCambio > 0),
    CONSTRAINT CK_TiposCambio_MonedaDestino CHECK (MonedaDestino = N'USD'),
    CONSTRAINT CK_TiposCambio_Clasificacion CHECK (EsRealOVariableSintetica IN (N'Real_Referencial', N'Variable_Sintetica', N'Paridad_Base'))
);
GO

-- 5.2 Tabla Original: Categorias
CREATE TABLE dbo.Categorias (
    IdCategoria TINYINT NOT NULL,
    NombreCategoria NVARCHAR(100) NOT NULL,
    Imagen NVARCHAR(255) NULL,
    CONSTRAINT PK_Categorias PRIMARY KEY CLUSTERED (IdCategoria)
);
GO

-- 5.3 Tabla Original Documentada: Proveedores
CREATE TABLE dbo.Proveedores (
    IdProveedor INT NOT NULL,
    NombreProveedor NVARCHAR(100) NOT NULL,
    Ciudad NVARCHAR(60) NOT NULL,
    Telefono NVARCHAR(50) NOT NULL,
    Email NVARCHAR(100) NOT NULL,
    CONSTRAINT PK_Proveedores PRIMARY KEY CLUSTERED (IdProveedor)
);
GO

-- 5.4 Tabla Original: Clientes
CREATE TABLE dbo.Clientes (
    Id_de_cliente NVARCHAR(50) NOT NULL,
    Nombre_de_compania NVARCHAR(100) NOT NULL,
    Nombre_del_contacto NVARCHAR(100) NOT NULL,
    Cargo_del_contacto NVARCHAR(100) NOT NULL,
    Direccion NVARCHAR(150) NOT NULL,
    Ciudad NVARCHAR(60) NOT NULL,
    Region NVARCHAR(60) NULL,
    Codigo_postal NVARCHAR(50) NULL,
    Pais NVARCHAR(60) NOT NULL,
    Telefono NVARCHAR(50) NOT NULL,
    Fax NVARCHAR(50) NULL,
    CONSTRAINT PK_Clientes PRIMARY KEY CLUSTERED (Id_de_cliente)
);
GO

-- 5.5 Tabla Original: Empleados
CREATE TABLE dbo.Empleados (
    Id_de_empleado TINYINT NOT NULL,
    Apellidos NVARCHAR(50) NOT NULL,
    Nombre NVARCHAR(50) NOT NULL,
    Cargo NVARCHAR(100) NOT NULL,
    Tratamiento NVARCHAR(50) NOT NULL,
    Fecha_de_nacimiento DATE NOT NULL,
    Fecha_de_contratacion DATE NOT NULL,
    Direccion NVARCHAR(150) NOT NULL,
    Ciudad NVARCHAR(60) NOT NULL,
    Region NVARCHAR(60) NULL,
    Codigo_postal NVARCHAR(50) NOT NULL,
    Pais NVARCHAR(60) NOT NULL,
    Telefono_de_domicilio NVARCHAR(50) NOT NULL,
    Extension SMALLINT NOT NULL,
    Notes NVARCHAR(500) NOT NULL,
    Jefe TINYINT NULL,
    CONSTRAINT PK_Empleados PRIMARY KEY CLUSTERED (Id_de_empleado),
    CONSTRAINT FK_Empleados_Jefe FOREIGN KEY (Jefe) REFERENCES dbo.Empleados (Id_de_empleado)
);
GO

-- 5.6 Tabla Original: Productos (Incluye combustibles líquidos, GNC, GLP, GNL, biocombustibles y lubricantes)
CREATE TABLE dbo.Productos (
    Id_de_producto INT NOT NULL,
    Nombre_de_producto NVARCHAR(120) NOT NULL,
    Proveedor INT NOT NULL,
    Categoria TINYINT NOT NULL,
    Cantidad_por_unidad NVARCHAR(100) NOT NULL,
    Precio_por_unidad DECIMAL(18, 2) NOT NULL,
    Unidades_en_existencia INT NOT NULL,
    Unidades_pedidas INT NOT NULL,
    Nivel_de_nuevo_pedido INT NOT NULL,
    Suspendido NVARCHAR(50) NOT NULL,
    CONSTRAINT PK_Productos PRIMARY KEY CLUSTERED (Id_de_producto),
    CONSTRAINT FK_Productos_Categorias FOREIGN KEY (Categoria) REFERENCES dbo.Categorias (IdCategoria),
    CONSTRAINT FK_Productos_Proveedores FOREIGN KEY (Proveedor) REFERENCES dbo.Proveedores (IdProveedor),
    CONSTRAINT CK_Productos_Precio CHECK (Precio_por_unidad >= 0)
);
GO

-- 5.7 Tabla Original: Pedidos (Pedidos Comerciales de Clientes, serie completa 2009 - 2026)
CREATE TABLE dbo.Pedidos (
    Id_de_pedido INT NOT NULL,
    Cliente NVARCHAR(50) NOT NULL,
    Empleado TINYINT NOT NULL,
    Fecha_de_pedido DATETIME2(0) NOT NULL,
    Forma_de_env TINYINT NOT NULL,
    Fecha_de_entrega DATE NOT NULL,
    CONSTRAINT PK_Pedidos PRIMARY KEY CLUSTERED (Id_de_pedido),
    CONSTRAINT FK_Pedidos_Clientes FOREIGN KEY (Cliente) REFERENCES dbo.Clientes (Id_de_cliente),
    CONSTRAINT FK_Pedidos_Empleados FOREIGN KEY (Empleado) REFERENCES dbo.Empleados (Id_de_empleado),
    CONSTRAINT CK_Pedidos_Corte2026 CHECK (Fecha_de_pedido >= '2009-01-01' AND Fecha_de_pedido <= '2026-10-25' AND Fecha_de_entrega <= '2026-10-25')
);
GO

-- 5.8 Tabla Original: [Detalles de Pedidos] (Serie completa 2009 - 2026)
CREATE TABLE dbo.[Detalles de Pedidos] (
    IdDetalle INT IDENTITY(1, 1) NOT NULL,
    Id_de_pedido INT NOT NULL,
    Producto INT NOT NULL,
    Cantidad INT NOT NULL,
    Descuento DECIMAL(5, 2) NOT NULL,
    Total DECIMAL(18, 2) NOT NULL,
    Costos_Directos DECIMAL(18, 2) NOT NULL,
    Costos_Indirectos DECIMAL(18, 2) NOT NULL,
    CONSTRAINT PK_Detalles_de_Pedidos PRIMARY KEY CLUSTERED (IdDetalle),
    CONSTRAINT FK_Detalles_de_Pedidos_Pedidos FOREIGN KEY (Id_de_pedido) REFERENCES dbo.Pedidos (Id_de_pedido),
    CONSTRAINT FK_Detalles_de_Pedidos_Productos FOREIGN KEY (Producto) REFERENCES dbo.Productos (Id_de_producto),
    CONSTRAINT CK_Detalles_Cantidad CHECK (Cantidad > 0)
);
GO

-- 5.9 Tabla Ampliada A: Estaciones (Nombres completos según provincia + capacidades de combustibles líquidos y de gas)
CREATE TABLE dbo.Estaciones (
    IdEstacion INT NOT NULL,
    NombreEstacion NVARCHAR(100) NOT NULL,
    Ciudad NVARCHAR(60) NOT NULL,
    Provincia NVARCHAR(60) NOT NULL,
    Tipo NVARCHAR(40) NOT NULL,
    FechaApertura DATE NOT NULL,
    FechaAlta DATE NOT NULL,
    Estado NVARCHAR(30) NOT NULL DEFAULT N'Operativa',
    CapacidadAlmacenamiento DECIMAL(18, 2) NOT NULL,
    CapacidadOperativa DECIMAL(18, 2) NOT NULL,
    CapacidadAlmacenamientoGas DECIMAL(18, 2) NOT NULL,
    CapacidadOperativaGas DECIMAL(18, 2) NOT NULL,
    TipoEstacion NVARCHAR(40) NOT NULL,
    PerfilDemanda NVARCHAR(50) NOT NULL,
    EsCapacidadSintetica BIT NOT NULL DEFAULT 1,
    CONSTRAINT PK_Estaciones PRIMARY KEY CLUSTERED (IdEstacion),
    CONSTRAINT CK_Estaciones_CapacidadAlm CHECK (CapacidadAlmacenamiento > 0),
    CONSTRAINT CK_Estaciones_CapacidadOp CHECK (CapacidadOperativa > 0),
    CONSTRAINT CK_Estaciones_CapacidadAlmGas CHECK (CapacidadAlmacenamientoGas > 0),
    CONSTRAINT CK_Estaciones_CapacidadOpGas CHECK (CapacidadOperativaGas > 0),
    CONSTRAINT CK_Estaciones_Estado CHECK (Estado IN (N'Operativa', N'En remodelación', N'Suspendida'))
);
GO

-- 5.10 Tabla Original Ampliada: Equipos (41 equipos cubriendo líquidos y gas en las 10 estaciones)
CREATE TABLE dbo.Equipos (
    IdEquipo INT NOT NULL,
    IdEstacion INT NOT NULL,
    TipoEquipo NVARCHAR(60) NOT NULL,
    Modelo NVARCHAR(60) NOT NULL,
    Estado NVARCHAR(40) NOT NULL,
    CONSTRAINT PK_Equipos PRIMARY KEY CLUSTERED (IdEquipo),
    CONSTRAINT FK_Equipos_Estaciones FOREIGN KEY (IdEstacion) REFERENCES dbo.Estaciones (IdEstacion)
);
GO

-- 5.11 Tabla Nueva B: PresupuestosAnualesEstacion (Serie histórica completa 2009 - 2026 en USD)
CREATE TABLE dbo.PresupuestosAnualesEstacion (
    IdPresupuesto INT NOT NULL,
    IdEstacion INT NOT NULL,
    Anio SMALLINT NOT NULL,
    DemandaAnualPresupuestada DECIMAL(18, 2) NOT NULL,
    DemandaAnualReal DECIMAL(18, 2) NOT NULL,
    CrecimientoDemandaPct DECIMAL(6, 2) NOT NULL,
    PresupuestoCombustibleUSD DECIMAL(18, 2) NOT NULL,
    PresupuestoMantenimientoUSD DECIMAL(18, 2) NOT NULL,
    PresupuestoOperativoUSD DECIMAL(18, 2) NOT NULL,
    PresupuestoTotalUSD DECIMAL(18, 2) NOT NULL,
    FechaAprobacion DATE NOT NULL,
    Observaciones NVARCHAR(300) NULL,
    CONSTRAINT PK_PresupuestosAnualesEstacion PRIMARY KEY CLUSTERED (IdPresupuesto),
    CONSTRAINT UQ_Presupuesto_Estacion_Anio UNIQUE NONCLUSTERED (IdEstacion, Anio),
    CONSTRAINT FK_Presupuestos_Estaciones FOREIGN KEY (IdEstacion) REFERENCES dbo.Estaciones (IdEstacion),
    CONSTRAINT CK_Presupuestos_Anio CHECK (Anio BETWEEN 2009 AND 2026),
    CONSTRAINT CK_Presupuestos_ImportesPositivos CHECK (
        DemandaAnualPresupuestada > 0 AND
        DemandaAnualReal >= 0 AND
        PresupuestoCombustibleUSD > 0 AND
        PresupuestoMantenimientoUSD > 0 AND
        PresupuestoOperativoUSD > 0 AND
        ABS(PresupuestoTotalUSD - (PresupuestoCombustibleUSD + PresupuestoMantenimientoUSD + PresupuestoOperativoUSD)) < 0.01
    ),
    CONSTRAINT CK_Presupuestos_FechaAprobacion CHECK (YEAR(FechaAprobacion) < Anio)
);
GO

-- 5.12 Tabla Ampliada C: Mantenimiento (Serie completa 2009 - 2026, 100 % expresada en USD en CostoUSD)
CREATE TABLE dbo.Mantenimiento (
    IdMantenimiento INT NOT NULL,
    IdEstacion INT NOT NULL,
    IdEquipo INT NOT NULL,
    Equipo NVARCHAR(100) NOT NULL,
    FechaProgramada DATE NOT NULL,
    FechaEjecucion DATE NULL,
    TipoMantenimiento NVARCHAR(50) NOT NULL,
    Estado NVARCHAR(30) NOT NULL,
    CostoUSD DECIMAL(18, 2) NOT NULL,
    EsFechaCritica BIT NOT NULL DEFAULT 0,
    CONSTRAINT PK_Mantenimiento PRIMARY KEY CLUSTERED (IdMantenimiento),
    CONSTRAINT FK_Mantenimiento_Estaciones FOREIGN KEY (IdEstacion) REFERENCES dbo.Estaciones (IdEstacion),
    CONSTRAINT FK_Mantenimiento_Equipos FOREIGN KEY (IdEquipo) REFERENCES dbo.Equipos (IdEquipo),
    CONSTRAINT CK_Mantenimiento_Estado CHECK (Estado IN (N'Programado', N'Ejecutado', N'Demorado', N'Cancelado', N'Pendiente')),
    CONSTRAINT CK_Mantenimiento_Costo CHECK (CostoUSD >= 0),
    CONSTRAINT CK_Mantenimiento_Corte2026 CHECK (
        FechaProgramada BETWEEN '2009-01-01' AND '2026-10-25' AND
        (FechaEjecucion IS NULL OR (FechaEjecucion >= FechaProgramada AND FechaEjecucion <= '2026-10-25'))
    )
);
GO

-- 5.13 Tabla Nueva D: PedidosEstaciones (Serie completa 2009 - 2026: reposición mayorista de combustibles líquidos y gases GNC/GLP/GNL)
CREATE TABLE dbo.PedidosEstaciones (
    IdPedidoEstacion INT NOT NULL,
    IdEstacion INT NOT NULL,
    IdProveedor INT NOT NULL,
    Proveedor NVARCHAR(100) NOT NULL,
    IdEmpleado TINYINT NOT NULL,
    FechaPedido DATE NOT NULL,
    FechaEntrega DATE NULL,
    EstadoPedido NVARCHAR(30) NOT NULL,
    MonedaOriginal NVARCHAR(10) NOT NULL,
    ImporteOriginal DECIMAL(18, 2) NOT NULL,
    IdTipoCambio INT NOT NULL,
    TipoCambioUSD DECIMAL(18, 4) NOT NULL,
    ImporteUSD DECIMAL(18, 2) NOT NULL,
    CONSTRAINT PK_PedidosEstaciones PRIMARY KEY CLUSTERED (IdPedidoEstacion),
    CONSTRAINT FK_PedidosEstaciones_Estaciones FOREIGN KEY (IdEstacion) REFERENCES dbo.Estaciones (IdEstacion),
    CONSTRAINT FK_PedidosEstaciones_Proveedores FOREIGN KEY (IdProveedor) REFERENCES dbo.Proveedores (IdProveedor),
    CONSTRAINT FK_PedidosEstaciones_Empleados FOREIGN KEY (IdEmpleado) REFERENCES dbo.Empleados (Id_de_empleado),
    CONSTRAINT FK_PedidosEstaciones_TiposCambio FOREIGN KEY (IdTipoCambio) REFERENCES dbo.TiposCambio (IdTipoCambio),
    CONSTRAINT CK_PedidosEstaciones_Estado CHECK (EstadoPedido IN (N'Entregado', N'En Tránsito', N'Demorado', N'Cancelado')),
    CONSTRAINT CK_PedidosEstaciones_Importes CHECK (ImporteOriginal > 0 AND ImporteUSD > 0 AND TipoCambioUSD > 0),
    CONSTRAINT CK_PedidosEstaciones_Corte2026 CHECK (
        FechaPedido BETWEEN '2009-01-01' AND '2026-10-25' AND
        (FechaEntrega IS NULL OR (FechaEntrega >= FechaPedido AND FechaEntrega <= '2026-10-25'))
    )
);
GO

-- 5.14 Tabla Nueva E: MovimientosCombustible (Serie completa 2009 - 2026: Entradas, Ventas, Transferencias y Ajustes de Combustibles Líquidos y Gases)
CREATE TABLE dbo.MovimientosCombustible (
    IdMovimiento INT NOT NULL,
    IdEstacion INT NOT NULL,
    IdPedidoEstacion INT NULL,
    IdProducto INT NULL,
    FechaMovimiento DATE NOT NULL,
    TipoMovimiento NVARCHAR(30) NOT NULL,
    TipoCombustible NVARCHAR(80) NOT NULL,
    Cantidad DECIMAL(18, 2) NOT NULL,
    UnidadMedida NVARCHAR(20) NOT NULL DEFAULT N'Litros',
    PrecioUnitarioUSD DECIMAL(18, 4) NOT NULL,
    CostoTotalUSD DECIMAL(18, 2) NOT NULL,
    Observaciones NVARCHAR(300) NULL,
    CONSTRAINT PK_MovimientosCombustible PRIMARY KEY CLUSTERED (IdMovimiento),
    CONSTRAINT FK_MovimientosCombustible_Estaciones FOREIGN KEY (IdEstacion) REFERENCES dbo.Estaciones (IdEstacion),
    CONSTRAINT FK_MovimientosCombustible_PedidosEst FOREIGN KEY (IdPedidoEstacion) REFERENCES dbo.PedidosEstaciones (IdPedidoEstacion),
    CONSTRAINT FK_MovimientosCombustible_Productos FOREIGN KEY (IdProducto) REFERENCES dbo.Productos (Id_de_producto),
    CONSTRAINT CK_Movimientos_Tipo CHECK (TipoMovimiento IN (N'Recepcion', N'Venta', N'Transferencia', N'Ajuste')),
    CONSTRAINT CK_Movimientos_Unidad CHECK (UnidadMedida IN (N'Litros', N'm3', N'kg')),
    CONSTRAINT CK_Movimientos_CantidadPositiva CHECK (Cantidad > 0 AND PrecioUnitarioUSD > 0 AND CostoTotalUSD > 0),
    CONSTRAINT CK_Movimientos_Corte2026 CHECK (FechaMovimiento BETWEEN '2009-01-01' AND '2026-10-25')
);
GO

