/*==============================================================================
  SECCIÓN 14. CONSULTAS DE ANÁLISIS PRESUPUESTARIO Y OPERATIVO (1 A 12)
  ------------------------------------------------------------------------------
  Nota de arquitectura SQL: Todas las consultas pre-agregan cada tabla de hechos
  en CTEs independientes al grano (IdEstacion, Anio) o (IdEstacion) antes de
  combinarlas, evitando la multiplicación artificial de importes por uniones
  entre relaciones uno a muchos.
==============================================================================*/

-- =============================================================================
-- CONSULTA 1: ¿Cuál fue el presupuesto anual y cuánto se gastó realmente en
--             mantenimiento por estación? (Serie completa 2009 - 2026)
-- =============================================================================
WITH GastoMantAnual AS (
    SELECT
        IdEstacion,
        YEAR(COALESCE(FechaEjecucion, FechaProgramada)) AS Anio,
        SUM(CASE WHEN Estado IN (N'Ejecutado', N'Demorado') THEN CostoUSD ELSE 0 END) AS GastoRealMantenimientoUSD,
        SUM(CASE WHEN TipoMantenimiento IN (N'Preventivo', N'Calibración', N'Inspección') AND Estado IN (N'Ejecutado', N'Demorado') THEN CostoUSD ELSE 0 END) AS GastoPreventivoUSD,
        SUM(CASE WHEN TipoMantenimiento IN (N'Correctivo', N'Reemplazo de componentes') AND Estado = N'Ejecutado' THEN CostoUSD ELSE 0 END) AS GastoCorrectivoUSD
    FROM dbo.Mantenimiento
    GROUP BY IdEstacion, YEAR(COALESCE(FechaEjecucion, FechaProgramada))
)
SELECT
    E.IdEstacion,
    E.NombreEstacion,
    E.Ciudad,
    P.Anio,
    P.PresupuestoMantenimientoUSD,
    ISNULL(G.GastoRealMantenimientoUSD, 0.00) AS GastoRealMantenimientoUSD,
    ISNULL(G.GastoPreventivoUSD, 0.00) AS GastoPreventivoUSD,
    ISNULL(G.GastoCorrectivoUSD, 0.00) AS GastoCorrectivoUSD,
    CAST(ISNULL(G.GastoRealMantenimientoUSD, 0.00) - P.PresupuestoMantenimientoUSD AS DECIMAL(18, 2)) AS DiferenciaUSD,
    CAST(((ISNULL(G.GastoRealMantenimientoUSD, 0.00) - P.PresupuestoMantenimientoUSD) / P.PresupuestoMantenimientoUSD) * 100.0 AS DECIMAL(6, 2)) AS DesviacionPct
FROM dbo.PresupuestosAnualesEstacion AS P
INNER JOIN dbo.Estaciones AS E ON P.IdEstacion = E.IdEstacion
LEFT JOIN GastoMantAnual AS G ON P.IdEstacion = G.IdEstacion AND P.Anio = G.Anio
ORDER BY P.IdEstacion, P.Anio;
GO

-- =============================================================================
-- CONSULTA 2: ¿Qué estaciones excedieron su presupuesto y en qué porcentaje?
-- =============================================================================
WITH GastoMantAnual AS (
    SELECT
        IdEstacion,
        YEAR(COALESCE(FechaEjecucion, FechaProgramada)) AS Anio,
        SUM(CASE WHEN Estado IN (N'Ejecutado', N'Demorado') THEN CostoUSD ELSE 0 END) AS GastoRealMantenimientoUSD
    FROM dbo.Mantenimiento
    GROUP BY IdEstacion, YEAR(COALESCE(FechaEjecucion, FechaProgramada))
)
SELECT
    E.IdEstacion,
    E.NombreEstacion,
    E.Ciudad,
    E.PerfilDemanda,
    P.Anio,
    P.PresupuestoMantenimientoUSD,
    G.GastoRealMantenimientoUSD,
    CAST(G.GastoRealMantenimientoUSD - P.PresupuestoMantenimientoUSD AS DECIMAL(18, 2)) AS ExcesoUSD,
    CAST(((G.GastoRealMantenimientoUSD - P.PresupuestoMantenimientoUSD) / P.PresupuestoMantenimientoUSD) * 100.0 AS DECIMAL(6, 2)) AS DesviacionPct
FROM dbo.PresupuestosAnualesEstacion AS P
INNER JOIN dbo.Estaciones AS E ON P.IdEstacion = E.IdEstacion
INNER JOIN GastoMantAnual AS G ON P.IdEstacion = G.IdEstacion AND P.Anio = G.Anio
WHERE G.GastoRealMantenimientoUSD > P.PresupuestoMantenimientoUSD
ORDER BY DesviacionPct DESC;
GO

-- =============================================================================
-- CONSULTA 3: ¿Qué estaciones mantuvieron su gasto dentro de los límites?
-- =============================================================================
WITH GastoMantAnual AS (
    SELECT
        IdEstacion,
        YEAR(COALESCE(FechaEjecucion, FechaProgramada)) AS Anio,
        SUM(CASE WHEN Estado IN (N'Ejecutado', N'Demorado') THEN CostoUSD ELSE 0 END) AS GastoRealMantenimientoUSD
    FROM dbo.Mantenimiento
    GROUP BY IdEstacion, YEAR(COALESCE(FechaEjecucion, FechaProgramada))
),
EvaluacionPresupuestaria AS (
    SELECT
        E.IdEstacion,
        E.NombreEstacion,
        E.Ciudad,
        E.PerfilDemanda,
        P.Anio,
        P.PresupuestoMantenimientoUSD,
        ISNULL(G.GastoRealMantenimientoUSD, 0.00) AS GastoRealMantenimientoUSD,
        CAST(((ISNULL(G.GastoRealMantenimientoUSD, 0.00) - P.PresupuestoMantenimientoUSD) / P.PresupuestoMantenimientoUSD) * 100.0 AS DECIMAL(6, 2)) AS DesviacionPct
    FROM dbo.PresupuestosAnualesEstacion AS P
    INNER JOIN dbo.Estaciones AS E ON P.IdEstacion = E.IdEstacion
    LEFT JOIN GastoMantAnual AS G ON P.IdEstacion = G.IdEstacion AND P.Anio = G.Anio
)
SELECT
    IdEstacion,
    NombreEstacion,
    Ciudad,
    PerfilDemanda,
    COUNT(*) AS TotalAniosEvaluados_2009_2026,
    SUM(CASE WHEN DesviacionPct <= 0.00 THEN 1 ELSE 0 END) AS AniosDentroDelPresupuesto,
    SUM(PresupuestoMantenimientoUSD) AS PresupuestoAcumuladoUSD,
    SUM(GastoRealMantenimientoUSD) AS GastoRealAcumuladoUSD,
    MAX(DesviacionPct) AS MayorDesviacionAnualPct
FROM EvaluacionPresupuestaria
GROUP BY IdEstacion, NombreEstacion, Ciudad, PerfilDemanda
HAVING MAX(DesviacionPct) <= 0.00
ORDER BY IdEstacion;
GO

-- =============================================================================
-- CONSULTA 4: ¿Cómo evolucionó la demanda entre 2009 y 2026 (con foco 2023-2026)?
-- =============================================================================
SELECT
    E.IdEstacion,
    E.NombreEstacion,
    E.Ciudad,
    E.PerfilDemanda,
    MAX(CASE WHEN P.Anio = 2009 THEN P.DemandaAnualReal END) AS DemandaReal2009,
    MAX(CASE WHEN P.Anio = 2015 THEN P.DemandaAnualReal END) AS DemandaReal2015,
    MAX(CASE WHEN P.Anio = 2020 THEN P.DemandaAnualReal END) AS DemandaReal2020,
    MAX(CASE WHEN P.Anio = 2023 THEN P.DemandaAnualReal END) AS DemandaReal2023,
    MAX(CASE WHEN P.Anio = 2024 THEN P.DemandaAnualReal END) AS DemandaReal2024,
    MAX(CASE WHEN P.Anio = 2025 THEN P.DemandaAnualReal END) AS DemandaReal2025,
    MAX(CASE WHEN P.Anio = 2026 THEN P.DemandaAnualReal END) AS DemandaObservada2026_YTD_25Oct,
    CAST(MAX(CASE WHEN P.Anio = 2026 THEN P.DemandaAnualReal END) * (365.0 / 298.0) AS DECIMAL(18, 2)) AS DemandaProyectadaCierre2026,
    CAST(((MAX(CASE WHEN P.Anio = 2025 THEN P.DemandaAnualReal END) - MAX(CASE WHEN P.Anio = 2023 THEN P.DemandaAnualReal END))
          / MAX(CASE WHEN P.Anio = 2023 THEN P.DemandaAnualReal END)) * 100.0 AS DECIMAL(6, 2)) AS CrecimientoAcumuladoObs_2023_2025_Pct
FROM dbo.Estaciones AS E
INNER JOIN dbo.PresupuestosAnualesEstacion AS P ON E.IdEstacion = P.IdEstacion
GROUP BY E.IdEstacion, E.NombreEstacion, E.Ciudad, E.PerfilDemanda
ORDER BY CrecimientoAcumuladoObs_2023_2025_Pct DESC;
GO

-- =============================================================================
-- CONSULTA 5: ¿Qué relación existe entre el crecimiento de la demanda y la
--             evolución del presupuesto? (Serie completa 2009 - 2026)
-- =============================================================================
SELECT
    E.IdEstacion,
    E.NombreEstacion,
    E.PerfilDemanda,
    P.Anio,
    P.CrecimientoDemandaPct AS CrecimientoDemandaPrevistoPct,
    P.DemandaAnualPresupuestada,
    P.PresupuestoCombustibleUSD,
    P.PresupuestoMantenimientoUSD,
    P.PresupuestoOperativoUSD,
    P.PresupuestoTotalUSD,
    CAST(
        (P.PresupuestoTotalUSD - LAG(P.PresupuestoTotalUSD) OVER (PARTITION BY P.IdEstacion ORDER BY P.Anio))
        / NULLIF(LAG(P.PresupuestoTotalUSD) OVER (PARTITION BY P.IdEstacion ORDER BY P.Anio), 0) * 100.0
    AS DECIMAL(6, 2)) AS VariacionAnualPresupuestoTotalPct,
    CAST(
        (P.PresupuestoMantenimientoUSD - LAG(P.PresupuestoMantenimientoUSD) OVER (PARTITION BY P.IdEstacion ORDER BY P.Anio))
        / NULLIF(LAG(P.PresupuestoMantenimientoUSD) OVER (PARTITION BY P.IdEstacion ORDER BY P.Anio), 0) * 100.0
    AS DECIMAL(6, 2)) AS VariacionAnualPresupuestoMantPct
FROM dbo.PresupuestosAnualesEstacion AS P
INNER JOIN dbo.Estaciones AS E ON P.IdEstacion = E.IdEstacion
ORDER BY P.IdEstacion, P.Anio;
GO

-- =============================================================================
-- CONSULTA 6: ¿Cuántos mantenimientos preventivos fueron planificados,
--             realizados, demorados u omitidos? (Serie completa 2009 - 2026)
-- =============================================================================
SELECT
    E.IdEstacion,
    E.NombreEstacion,
    E.PerfilDemanda,
    COUNT(CASE WHEN M.TipoMantenimiento = N'Preventivo' THEN 1 END) AS TotalPreventivosPlanificados_2009_2026,
    COUNT(CASE WHEN M.TipoMantenimiento = N'Preventivo' AND M.Estado = N'Ejecutado' THEN 1 END) AS PreventivosRealizadosEnTermino,
    COUNT(CASE WHEN M.TipoMantenimiento = N'Preventivo' AND M.Estado = N'Demorado' THEN 1 END) AS PreventivosDemorados,
    COUNT(CASE WHEN M.TipoMantenimiento = N'Preventivo' AND M.Estado = N'Cancelado' THEN 1 END) AS PreventivosOmitidosCancelados,
    COUNT(CASE WHEN M.TipoMantenimiento = N'Preventivo' AND M.Estado IN (N'Programado', N'Pendiente') THEN 1 END) AS PreventivosProgramadosOPendientes,
    COUNT(CASE WHEN M.TipoMantenimiento = N'Preventivo' AND M.EsFechaCritica = 1 AND M.Estado IN (N'Demorado', N'Cancelado') THEN 1 END) AS IncumplimientosEnFechaCritica
FROM dbo.Estaciones AS E
LEFT JOIN dbo.Mantenimiento AS M ON E.IdEstacion = M.IdEstacion
GROUP BY E.IdEstacion, E.NombreEstacion, E.PerfilDemanda
ORDER BY IncumplimientosEnFechaCritica DESC, E.IdEstacion;
GO

-- =============================================================================
-- CONSULTA 7: ¿Cuánto se gastó en mantenimiento correctivo después de
--             incumplimientos preventivos en fechas críticas?
-- =============================================================================
WITH PreventivosIncumplidos AS (
    SELECT
        IdEstacion,
        IdEquipo,
        Equipo,
        YEAR(FechaProgramada) AS Anio,
        MIN(FechaProgramada) AS FechaPreventivoIncumplido,
        MAX(Estado) AS EstadoPreventivoCritico
    FROM dbo.Mantenimiento
    WHERE TipoMantenimiento = N'Preventivo'
      AND EsFechaCritica = 1
      AND Estado IN (N'Demorado', N'Cancelado')
    GROUP BY IdEstacion, IdEquipo, Equipo, YEAR(FechaProgramada)
)
SELECT
    E.IdEstacion,
    E.NombreEstacion,
    PI.Anio,
    PI.Equipo,
    PI.FechaPreventivoIncumplido,
    PI.EstadoPreventivoCritico,
    COUNT(MC.IdMantenimiento) AS CantidadCorrectivosPosteriores,
    SUM(MC.CostoUSD) AS GastoCorrectivoPosteriorUSD
FROM PreventivosIncumplidos AS PI
INNER JOIN dbo.Estaciones AS E ON PI.IdEstacion = E.IdEstacion
INNER JOIN dbo.Mantenimiento AS MC
    ON MC.IdEstacion = PI.IdEstacion
   AND MC.IdEquipo = PI.IdEquipo
   AND YEAR(MC.FechaProgramada) = PI.Anio
   AND MC.TipoMantenimiento = N'Correctivo'
   AND MC.FechaProgramada > PI.FechaPreventivoIncumplido
GROUP BY
    E.IdEstacion,
    E.NombreEstacion,
    PI.Anio,
    PI.Equipo,
    PI.FechaPreventivoIncumplido,
    PI.EstadoPreventivoCritico
ORDER BY GastoCorrectivoPosteriorUSD DESC;
GO

-- =============================================================================
-- CONSULTA 8: ¿Qué estaciones presentan los mayores costos de mantenimiento
--             por unidad de combustible y gas comercializado? (2009 - 2026 y 2023 - 2026)
-- =============================================================================
WITH VentasEstacion AS (
    SELECT
        IdEstacion,
        SUM(CASE WHEN UnidadMedida = N'Litros' THEN Cantidad ELSE 0 END) AS TotalLitrosLiquidos_2009_2026,
        SUM(CASE WHEN UnidadMedida IN (N'm3', N'kg') THEN Cantidad ELSE 0 END) AS TotalUnidadesGas_2009_2026,
        SUM(Cantidad) AS TotalUnidadesEnergeticas_2009_2026,
        SUM(CASE WHEN YEAR(FechaMovimiento) BETWEEN 2023 AND 2026 THEN Cantidad ELSE 0 END) AS TotalUnidadesEnergeticas_2023_2026
    FROM dbo.MovimientosCombustible
    WHERE TipoMovimiento = N'Venta'
    GROUP BY IdEstacion
),
GastoMantEstacion AS (
    SELECT
        IdEstacion,
        SUM(CASE WHEN Estado IN (N'Ejecutado', N'Demorado') THEN CostoUSD ELSE 0 END) AS CostoMantTotal_2009_2026_USD,
        SUM(CASE WHEN YEAR(COALESCE(FechaEjecucion, FechaProgramada)) BETWEEN 2023 AND 2026 AND Estado IN (N'Ejecutado', N'Demorado') THEN CostoUSD ELSE 0 END) AS CostoMant_2023_2026_USD,
        SUM(CASE WHEN YEAR(COALESCE(FechaEjecucion, FechaProgramada)) BETWEEN 2023 AND 2026 AND TipoMantenimiento = N'Correctivo' AND Estado = N'Ejecutado' THEN CostoUSD ELSE 0 END) AS CostoCorrectivo_2023_2026_USD
    FROM dbo.Mantenimiento
    GROUP BY IdEstacion
)
SELECT
    E.IdEstacion,
    E.NombreEstacion,
    E.Ciudad,
    E.PerfilDemanda,
    V.TotalLitrosLiquidos_2009_2026,
    V.TotalUnidadesGas_2009_2026,
    V.TotalUnidadesEnergeticas_2023_2026,
    M.CostoMantTotal_2009_2026_USD,
    M.CostoMant_2023_2026_USD,
    M.CostoCorrectivo_2023_2026_USD,
    CAST((M.CostoMant_2023_2026_USD / NULLIF(V.TotalUnidadesEnergeticas_2023_2026, 0)) * 1000.0 AS DECIMAL(10, 2)) AS CostoMantPorCada1000Unidades_2023_2026_USD
FROM dbo.Estaciones AS E
INNER JOIN VentasEstacion AS V ON E.IdEstacion = V.IdEstacion
INNER JOIN GastoMantEstacion AS M ON E.IdEstacion = M.IdEstacion
ORDER BY CostoMantPorCada1000Unidades_2023_2026_USD DESC;
GO

-- =============================================================================
-- CONSULTA 9: ¿Cuál es el volumen de entradas, salidas y saldo de combustibles
--             líquidos y de gases (GNC / GLP / GNL) por estación (2009 - 2026)?
-- =============================================================================
SELECT
    E.IdEstacion,
    E.NombreEstacion,
    -- Balance de Combustibles Líquidos (Litros)
    E.CapacidadAlmacenamiento AS CapacidadLiquidos_L,
    SUM(CASE WHEN MC.UnidadMedida = N'Litros' AND MC.TipoMovimiento = N'Recepcion' THEN MC.Cantidad ELSE 0 END) AS EntradasLiquidos_L,
    SUM(CASE WHEN MC.UnidadMedida = N'Litros' AND MC.TipoMovimiento IN (N'Venta', N'Transferencia', N'Ajuste') THEN MC.Cantidad ELSE 0 END) AS SalidasLiquidos_L,
    CAST(
        SUM(CASE WHEN MC.UnidadMedida = N'Litros' AND MC.TipoMovimiento = N'Recepcion' THEN MC.Cantidad ELSE 0 END) -
        SUM(CASE WHEN MC.UnidadMedida = N'Litros' AND MC.TipoMovimiento IN (N'Venta', N'Transferencia', N'Ajuste') THEN MC.Cantidad ELSE 0 END)
    AS DECIMAL(18, 2)) AS SaldoFinalLiquidos_L,
    CAST(
        ((SUM(CASE WHEN MC.UnidadMedida = N'Litros' AND MC.TipoMovimiento = N'Recepcion' THEN MC.Cantidad ELSE 0 END) -
          SUM(CASE WHEN MC.UnidadMedida = N'Litros' AND MC.TipoMovimiento IN (N'Venta', N'Transferencia', N'Ajuste') THEN MC.Cantidad ELSE 0 END))
         / E.CapacidadAlmacenamiento) * 100.0
    AS DECIMAL(6, 2)) AS OcupacionLiquidosPct,
    -- Balance de Gases: GNC / GLP / GNL (m3 y kg eq.)
    E.CapacidadAlmacenamientoGas AS CapacidadGas_Unidades,
    SUM(CASE WHEN MC.UnidadMedida IN (N'm3', N'kg') AND MC.TipoMovimiento = N'Recepcion' THEN MC.Cantidad ELSE 0 END) AS EntradasGas_Unidades,
    SUM(CASE WHEN MC.UnidadMedida IN (N'm3', N'kg') AND MC.TipoMovimiento IN (N'Venta', N'Transferencia', N'Ajuste') THEN MC.Cantidad ELSE 0 END) AS SalidasGas_Unidades,
    CAST(
        SUM(CASE WHEN MC.UnidadMedida IN (N'm3', N'kg') AND MC.TipoMovimiento = N'Recepcion' THEN MC.Cantidad ELSE 0 END) -
        SUM(CASE WHEN MC.UnidadMedida IN (N'm3', N'kg') AND MC.TipoMovimiento IN (N'Venta', N'Transferencia', N'Ajuste') THEN MC.Cantidad ELSE 0 END)
    AS DECIMAL(18, 2)) AS SaldoFinalGas_Unidades,
    CAST(
        ((SUM(CASE WHEN MC.UnidadMedida IN (N'm3', N'kg') AND MC.TipoMovimiento = N'Recepcion' THEN MC.Cantidad ELSE 0 END) -
          SUM(CASE WHEN MC.UnidadMedida IN (N'm3', N'kg') AND MC.TipoMovimiento IN (N'Venta', N'Transferencia', N'Ajuste') THEN MC.Cantidad ELSE 0 END))
         / E.CapacidadAlmacenamientoGas) * 100.0
    AS DECIMAL(6, 2)) AS OcupacionGasPct
FROM dbo.Estaciones AS E
INNER JOIN dbo.MovimientosCombustible AS MC ON E.IdEstacion = MC.IdEstacion
GROUP BY E.IdEstacion, E.NombreEstacion, E.CapacidadAlmacenamiento, E.CapacidadAlmacenamientoGas
ORDER BY E.IdEstacion;
GO

-- =============================================================================
-- CONSULTA 10: ¿Qué diferencias existen entre los presupuestos anuales y los
--              gastos reales en USD? (Serie completa 2009 - 2026 sin faltantes)
-- =============================================================================
WITH ComprasCombAnual AS (
    SELECT
        IdEstacion,
        YEAR(FechaPedido) AS Anio,
        SUM(CASE WHEN EstadoPedido = N'Entregado' THEN ImporteUSD ELSE 0 END) AS GastoRealCombustibleYGasUSD
    FROM dbo.PedidosEstaciones
    GROUP BY IdEstacion, YEAR(FechaPedido)
),
GastoMantAnual AS (
    SELECT
        IdEstacion,
        YEAR(COALESCE(FechaEjecucion, FechaProgramada)) AS Anio,
        SUM(CASE WHEN Estado IN (N'Ejecutado', N'Demorado') THEN CostoUSD ELSE 0 END) AS GastoRealMantenimientoUSD
    FROM dbo.Mantenimiento
    GROUP BY IdEstacion, YEAR(COALESCE(FechaEjecucion, FechaProgramada))
)
SELECT
    P.Anio,
    E.IdEstacion,
    E.NombreEstacion,
    P.PresupuestoCombustibleUSD,
    ISNULL(C.GastoRealCombustibleYGasUSD, 0.00) AS GastoRealCombustibleYGasUSD,
    CAST(ISNULL(C.GastoRealCombustibleYGasUSD, 0.00) - P.PresupuestoCombustibleUSD AS DECIMAL(18, 2)) AS DiferenciaCombustibleUSD,
    P.PresupuestoMantenimientoUSD,
    ISNULL(M.GastoRealMantenimientoUSD, 0.00) AS GastoRealMantenimientoUSD,
    CAST(ISNULL(M.GastoRealMantenimientoUSD, 0.00) - P.PresupuestoMantenimientoUSD AS DECIMAL(18, 2)) AS DiferenciaMantenimientoUSD
FROM dbo.PresupuestosAnualesEstacion AS P
INNER JOIN dbo.Estaciones AS E ON P.IdEstacion = E.IdEstacion
LEFT JOIN ComprasCombAnual AS C ON P.IdEstacion = C.IdEstacion AND P.Anio = C.Anio
LEFT JOIN GastoMantAnual AS M ON P.IdEstacion = M.IdEstacion AND P.Anio = M.Anio
ORDER BY P.Anio, E.IdEstacion;
GO

-- =============================================================================
-- CONSULTA 11: ¿Qué estaciones presentan valores atípicos que requieren revisión?
-- =============================================================================
WITH ResumenAnualMant AS (
    SELECT
        IdEstacion,
        YEAR(COALESCE(FechaEjecucion, FechaProgramada)) AS Anio,
        SUM(CASE WHEN Estado IN (N'Ejecutado', N'Demorado') THEN CostoUSD ELSE 0 END) AS GastoRealMantUSD,
        SUM(CASE WHEN TipoMantenimiento = N'Correctivo' AND Estado = N'Ejecutado' THEN CostoUSD ELSE 0 END) AS GastoCorrectivoUSD,
        COUNT(CASE WHEN TipoMantenimiento = N'Preventivo' AND EsFechaCritica = 1 AND Estado IN (N'Demorado', N'Cancelado') THEN 1 END) AS IncumplimientosCriticos
    FROM dbo.Mantenimiento
    WHERE YEAR(COALESCE(FechaEjecucion, FechaProgramada)) BETWEEN 2023 AND 2026
    GROUP BY IdEstacion, YEAR(COALESCE(FechaEjecucion, FechaProgramada))
)
SELECT
    E.IdEstacion,
    E.NombreEstacion,
    E.Ciudad,
    E.PerfilDemanda,
    P.Anio,
    P.PresupuestoMantenimientoUSD,
    R.GastoRealMantUSD,
    CAST(((R.GastoRealMantUSD - P.PresupuestoMantenimientoUSD) / P.PresupuestoMantenimientoUSD) * 100.0 AS DECIMAL(6, 2)) AS DesviacionPresupuestariaPct,
    CAST((R.GastoCorrectivoUSD / NULLIF(R.GastoRealMantUSD, 0)) * 100.0 AS DECIMAL(6, 2)) AS ParticipacionCorrectivoPct,
    CAST((R.GastoRealMantUSD / NULLIF(P.DemandaAnualReal, 0)) * 1000.0 AS DECIMAL(10, 2)) AS CostoMantPor1000Unidades_USD,
    R.IncumplimientosCriticos,
    CASE
        WHEN ((R.GastoRealMantUSD - P.PresupuestoMantenimientoUSD) / P.PresupuestoMantenimientoUSD) * 100.0 > 8.0
            THEN N'ALERTA ALTA: Sobrecosto cercano al límite del 10% tras omisión preventiva'
        WHEN ((R.GastoRealMantUSD - P.PresupuestoMantenimientoUSD) / P.PresupuestoMantenimientoUSD) * 100.0 > 5.0
            THEN N'ALERTA MEDIA: Exceso presupuestario (>5%) asociado a correctivos'
        WHEN (R.GastoRealMantUSD / NULLIF(P.DemandaAnualReal, 0)) * 1000.0 > 12.0
            THEN N'REVISIÓN OPERATIVA: Alto costo de mantenimiento unitario por caída de demanda'
        ELSE N'Normal'
    END AS DiagnosticoAuditoria
FROM dbo.PresupuestosAnualesEstacion AS P
INNER JOIN dbo.Estaciones AS E ON P.IdEstacion = E.IdEstacion
INNER JOIN ResumenAnualMant AS R ON P.IdEstacion = R.IdEstacion AND P.Anio = R.Anio
WHERE ((R.GastoRealMantUSD - P.PresupuestoMantenimientoUSD) / P.PresupuestoMantenimientoUSD) * 100.0 > 5.0
   OR (R.GastoRealMantUSD / NULLIF(P.DemandaAnualReal, 0)) * 1000.0 > 12.0
ORDER BY DesviacionPresupuestariaPct DESC;
GO

-- =============================================================================
-- CONSULTA 12: ¿Cómo se compara 2026 con el mismo período de 2025?
-- =============================================================================
WITH MantEquivalenteYTD AS (
    SELECT
        IdEstacion,
        SUM(CASE WHEN YEAR(COALESCE(FechaEjecucion, FechaProgramada)) = 2025
                  AND MONTH(COALESCE(FechaEjecucion, FechaProgramada)) * 100 + DAY(COALESCE(FechaEjecucion, FechaProgramada)) <= 1025
                  AND Estado IN (N'Ejecutado', N'Demorado') THEN CostoUSD ELSE 0 END) AS GastoMant2025_Al25Oct_USD,
        SUM(CASE WHEN YEAR(COALESCE(FechaEjecucion, FechaProgramada)) = 2026
                  AND MONTH(COALESCE(FechaEjecucion, FechaProgramada)) * 100 + DAY(COALESCE(FechaEjecucion, FechaProgramada)) <= 1025
                  AND Estado IN (N'Ejecutado', N'Demorado') THEN CostoUSD ELSE 0 END) AS GastoMant2026_ObsAl25Oct_USD
    FROM dbo.Mantenimiento
    GROUP BY IdEstacion
)
SELECT
    E.IdEstacion,
    E.NombreEstacion,
    E.PerfilDemanda,
    P25.DemandaAnualReal AS Demanda2025_AnualCompleta,
    CAST(P25.DemandaAnualReal * (298.0 / 365.0) AS DECIMAL(18, 2)) AS Demanda2025_EquivAl25Oct,
    P26.DemandaAnualReal AS Demanda2026_ObservadaAl25Oct,
    CAST(((P26.DemandaAnualReal - (P25.DemandaAnualReal * (298.0 / 365.0))) / (P25.DemandaAnualReal * (298.0 / 365.0))) * 100.0 AS DECIMAL(6, 2)) AS VarDemandaYTD_2026vs2025_Pct,
    CAST(P26.DemandaAnualReal * (365.0 / 298.0) AS DECIMAL(18, 2)) AS Demanda2026_ProyeccionCierreAnual,
    M.GastoMant2025_Al25Oct_USD,
    M.GastoMant2026_ObsAl25Oct_USD,
    CAST(((M.GastoMant2026_ObsAl25Oct_USD - M.GastoMant2025_Al25Oct_USD) / NULLIF(M.GastoMant2025_Al25Oct_USD, 0)) * 100.0 AS DECIMAL(6, 2)) AS VarGastoMantYTD_2026vs2025_Pct,
    P26.PresupuestoMantenimientoUSD AS PresupuestoMant2026_Anual_USD
FROM dbo.Estaciones AS E
INNER JOIN dbo.PresupuestosAnualesEstacion AS P25 ON E.IdEstacion = P25.IdEstacion AND P25.Anio = 2025
INNER JOIN dbo.PresupuestosAnualesEstacion AS P26 ON E.IdEstacion = P26.IdEstacion AND P26.Anio = 2026
INNER JOIN MantEquivalenteYTD AS M ON E.IdEstacion = M.IdEstacion
ORDER BY E.IdEstacion;
GO

/*==============================================================================
  SECCIÓN 15. CONSULTAS DE VALIDACIÓN DE INTEGRIDAD Y DETECCIÓN DE ANOMALÍAS
  ------------------------------------------------------------------------------
  Todas las validaciones están diseñadas como pruebas de auditoría donde el
  resultado esperado de registros erróneos o inconsistentes es exactamente 0.
==============================================================================*/

-- Validación 15.1: Verificar que no existan presupuestos anuales duplicados por estación (2009-2026)
SELECT IdEstacion, Anio, COUNT(*) AS CantidadDuplicados
FROM dbo.PresupuestosAnualesEstacion
GROUP BY IdEstacion, Anio
HAVING COUNT(*) > 1;

-- Validación 15.2: Verificar que ningún exceso de mantenimiento supere el 10,00 % del presupuesto aprobado (2009-2026)
WITH ControlDesvio AS (
    SELECT
        P.IdEstacion,
        P.Anio,
        P.PresupuestoMantenimientoUSD,
        SUM(CASE WHEN M.Estado IN (N'Ejecutado', N'Demorado') THEN M.CostoUSD ELSE 0 END) AS GastoRealUSD,
        CAST(((SUM(CASE WHEN M.Estado IN (N'Ejecutado', N'Demorado') THEN M.CostoUSD ELSE 0 END) - P.PresupuestoMantenimientoUSD) / P.PresupuestoMantenimientoUSD) * 100.0 AS DECIMAL(6, 2)) AS DesviacionPct
    FROM dbo.PresupuestosAnualesEstacion AS P
    INNER JOIN dbo.Mantenimiento AS M ON P.IdEstacion = M.IdEstacion AND P.Anio = YEAR(COALESCE(M.FechaEjecucion, M.FechaProgramada))
    GROUP BY P.IdEstacion, P.Anio, P.PresupuestoMantenimientoUSD
)
SELECT *
FROM ControlDesvio
WHERE DesviacionPct > 10.00;

-- Validación 15.3: Verificar que no existan operaciones posteriores al 25 de octubre de 2026
SELECT N'Pedidos' AS Tabla, COUNT(*) AS RegistrosPosterioresAlCorte
FROM dbo.Pedidos
WHERE Fecha_de_pedido > '2026-10-25' OR Fecha_de_entrega > '2026-10-25'
UNION ALL
SELECT N'Mantenimiento', COUNT(*)
FROM dbo.Mantenimiento
WHERE FechaProgramada > '2026-10-25' OR FechaEjecucion > '2026-10-25'
UNION ALL
SELECT N'PedidosEstaciones', COUNT(*)
FROM dbo.PedidosEstaciones
WHERE FechaPedido > '2026-10-25' OR FechaEntrega > '2026-10-25'
UNION ALL
SELECT N'MovimientosCombustible', COUNT(*)
FROM dbo.MovimientosCombustible
WHERE FechaMovimiento > '2026-10-25';

-- Validación 15.4: Verificar coherencia de saldos de inventario de combustibles líquidos y de gas (2009-2026)
WITH ControlSaldos AS (
    SELECT
        E.IdEstacion,
        E.NombreEstacion,
        E.CapacidadAlmacenamiento,
        E.CapacidadAlmacenamientoGas,
        SUM(CASE WHEN MC.UnidadMedida = N'Litros' AND MC.TipoMovimiento = N'Recepcion' THEN MC.Cantidad ELSE 0 END) -
        SUM(CASE WHEN MC.UnidadMedida = N'Litros' AND MC.TipoMovimiento IN (N'Venta', N'Transferencia', N'Ajuste') THEN MC.Cantidad ELSE 0 END) AS SaldoFinalLiquidos,
        SUM(CASE WHEN MC.UnidadMedida IN (N'm3', N'kg') AND MC.TipoMovimiento = N'Recepcion' THEN MC.Cantidad ELSE 0 END) -
        SUM(CASE WHEN MC.UnidadMedida IN (N'm3', N'kg') AND MC.TipoMovimiento IN (N'Venta', N'Transferencia', N'Ajuste') THEN MC.Cantidad ELSE 0 END) AS SaldoFinalGas
    FROM dbo.Estaciones AS E
    INNER JOIN dbo.MovimientosCombustible AS MC ON E.IdEstacion = MC.IdEstacion
    GROUP BY E.IdEstacion, E.NombreEstacion, E.CapacidadAlmacenamiento, E.CapacidadAlmacenamientoGas
)
SELECT *
FROM ControlSaldos
WHERE SaldoFinalLiquidos < 0 OR SaldoFinalLiquidos > CapacidadAlmacenamiento
   OR SaldoFinalGas < 0 OR SaldoFinalGas > CapacidadAlmacenamientoGas;

-- Validación 15.5: Verificar trazabilidad matemática de conversiones monetarias en PedidosEstaciones
SELECT N'PedidosEstaciones_ErrorConversion' AS Control, COUNT(*) AS CasosInconsistentes
FROM dbo.PedidosEstaciones
WHERE ABS(ImporteUSD - ROUND(ImporteOriginal / TipoCambioUSD, 2)) > 0.01;

-- Validación 15.6: Verificar que NO existan años faltantes (2009 a 2026 = 18 años) en Pedidos de Clientes,
--                  PresupuestosAnualesEstacion, Mantenimiento, PedidosEstaciones ni MovimientosCombustible
SELECT Tabla, AniosConRegistros, (18 - AniosConRegistros) AS AniosFaltantes
FROM (
    SELECT N'Pedidos (Clientes)' AS Tabla, COUNT(DISTINCT YEAR(Fecha_de_pedido)) AS AniosConRegistros FROM dbo.Pedidos
    UNION ALL
    SELECT N'PresupuestosAnualesEstacion', COUNT(DISTINCT Anio) FROM dbo.PresupuestosAnualesEstacion
    UNION ALL
    SELECT N'Mantenimiento', COUNT(DISTINCT YEAR(COALESCE(FechaEjecucion, FechaProgramada))) FROM dbo.Mantenimiento
    UNION ALL
    SELECT N'PedidosEstaciones', COUNT(DISTINCT YEAR(FechaPedido)) FROM dbo.PedidosEstaciones
    UNION ALL
    SELECT N'MovimientosCombustible', COUNT(DISTINCT YEAR(FechaMovimiento)) FROM dbo.MovimientosCombustible
) AS AuditoriaCobertura
WHERE AniosConRegistros < 18;
GO